import{_ as s,C as o,o as r,c as n,j as t,a as i,E as h,a6 as d}from"./chunks/framework.CCKCzdWs.js";const k=JSON.parse(`{"title":"Watch a local test","description":"Watch the page of a Playwright test while it runs on your machine, from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app: up to ten images a second, through its next tests and stops.","frontmatter":{"title":"Watch a local test","description":"Watch the page of a Playwright test while it runs on your machine, from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app: up to ten images a second, through its next tests and stops.","lang":"en-US","head":[["link",{"rel":"canonical","href":"https://piwitests.dev/features/watch-running-test.html"}],["meta",{"property":"og:url","content":"https://piwitests.dev/features/watch-running-test.html"}],["meta",{"property":"og:title","content":"Watch a local test | Piwi for Playwright"}],["meta",{"property":"og:description","content":"Watch the page of a Playwright test while it runs on your machine, from VS Code, a JetBrains IDE, Piwi Picker's Runs window or the desktop app: up to ten images a second, through its next tests and stops."}]]},"headers":[],"relativePath":"features/watch-running-test.md","filePath":"features/watch-running-test.md","lastUpdated":1794759890000}`),c={name:"features/watch-running-test.md"};function l(w,e,p,u,g,f){const a=o("Needs");return r(),n("div",null,[e[0]||(e[0]=t("h1",{id:"watch-a-local-test",tabindex:"-1"},[i("Watch a local test "),t("a",{class:"header-anchor",href:"#watch-a-local-test","aria-label":'Permalink to "Watch a local test"'},"​")],-1)),h(a,{reporter:"",fixtures:""}),e[1]||(e[1]=d('<p><strong>Watch</strong> in your own tools shows a test&#39;s page in your editor, Piwi Picker&#39;s Runs window or the desktop app, in a run on your machine or a remote container, read-only in a CI run of your branch. On the team instance, it is the <a href="./live-view.html">live view</a>; a run&#39;s progress and stops: <a href="./watch-a-run.html">Follow a run</a>. The page shows up to ten images a second, through the test&#39;s next tests and stops, and the worker Playwright starts in its place after a failure. It needs <code>@piwitests/reporter</code> after 0.67.0 and the <a href="/guide/capture-fixtures.html">capture fixtures</a>. Nothing leaves your machine: <a href="#what-is-sent-and-kept">what is sent</a>.</p><h2 id="where-to-watch" tabindex="-1">Where to watch <a class="header-anchor" href="#where-to-watch" aria-label="Permalink to &quot;Where to watch&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Where</th><th>Open it</th><th>At a stop</th></tr></thead><tbody><tr><td>VS Code</td><td><strong>Piwi: Watch a worker&#39;s test</strong>, the eye on a worker&#39;s row of the Piwi panel&#39;s <strong>Runs</strong> view, or the status bar&#39;s menu during a run: <code>Piwi: worker 2</code> beside the editor</td><td>While it watches in sight, a headless stop shows there, not on the paused page, with its controls, <strong>Interact</strong> and the pick on a click</td></tr><tr><td>JetBrains IDEs</td><td><strong>Tools → Piwi → Watch a worker&#39;s test</strong>, or a worker&#39;s row&#39;s right-click in the Piwi tool window&#39;s <strong>Runs</strong> tab: its <strong>Worker 2</strong> tab</td><td>While it watches in sight, a headless stop shows there, not on the <strong>Worker 2</strong> page tab, with its controls and <strong>Interact</strong></td></tr><tr><td>Piwi Picker</td><td><strong>Watch</strong> on a worker&#39;s row of the <a href="./runs-window.html#watch-live">Runs window</a></td><td>Its controls above the view; the stopped worker scrolls into view</td></tr><tr><td>Desktop app</td><td><strong>Watch</strong> on a running row of its own runs opens the <a href="./desktop-runs.html#watch">Local runs</a> tray on it</td><td>The tray shows the stopped worker, behind its tab in a run of several</td></tr></tbody></table><p><strong>Pause and watch</strong>, which also stops the test before its next call, is <strong>Piwi: Pause and watch a worker&#39;s test</strong> (<strong>Tools → Piwi → …</strong>), and a button beside <strong>Watch</strong> in the Runs window and the desktop app. With several workers, the editor asks which.</p><p>While a run is in progress, VS Code&#39;s <strong>Runs</strong> view and the JetBrains <strong>Runs</strong> tab list each run with how far it is, each worker by its lane with its test and whether it stands stopped, and the run&#39;s page on the dashboard. A row opens the stopped line or the test, and its buttons (VS Code) or its right-click (JetBrains) offer <strong>Watch</strong>, <strong>Pause and watch</strong> on a test that can pause, <strong>Resume</strong>, <strong>Step</strong> except at a failure, and, for a run the editor started, <strong>Stop the run</strong>. A run that can hold its failures says when it does (<code>Hold failures on</code>) and turns it over from its row.</p><h2 id="a-ci-run-of-your-branch" tabindex="-1">A CI run of your branch <a class="header-anchor" href="#a-ci-run-of-your-branch" aria-label="Permalink to &quot;A CI run of your branch&quot;">​</a></h2><p>A CI run of your branch shows beside your runs, read-only, and <strong>Watch</strong> opens its lanes from the team instance: <a href="./editor-ci-runs.html">CI runs in your editor</a>.</p><h2 id="what-you-see" tabindex="-1">What you see <a class="header-anchor" href="#what-you-see" aria-label="Permalink to &quot;What you see&quot;">​</a></h2><p>Each view names the worker by its lane (<code>Worker 2</code>) and says what it does: its running test, the call a Pause waits in, its stop, between tests, or starting. Across a <strong>Step</strong>, a <strong>Resume</strong> or between two tests, the last image stays until the next one comes, dimmed in VS Code, the Runs window and the desktop app, the last two marking it <strong>Running…</strong>. A still page sends none. Watching pauses while the view is out of sight (another tab in front, a minimized Runs window) and starts again as it shows. It ends when you turn it off or close the view, or as the run ends.</p><h2 id="beside-the-image" tabindex="-1">Beside the image <a class="header-anchor" href="#beside-the-image" aria-label="Permalink to &quot;Beside the image&quot;">​</a></h2><p>Under the image, the editor&#39;s view, a CI run&#39;s lane included, the Runs window and the desktop app&#39;s tray show what the pixels cannot: why the test waits, the page&#39;s events, its text and a filmstrip of its calls (<a href="./live-view-layers.html#in-your-own-tools">in your own tools</a>). While an editor watches a worker of your run, the line of the call its test is in is marked until the test ends or stops, the call named after it (VS Code dims the line, <code>Worker 2 · Click getByRole(&#39;button&#39;)</code>; a JetBrains IDE adds an inlay), and the page&#39;s events go to VS Code&#39;s <code>Piwi: Page</code> output, its console and uncaught errors to the JetBrains Piwi tool window&#39;s <strong>Page</strong> tab, each test named as it begins.</p><h2 id="open-the-trace-so-far" tabindex="-1">Open the trace so far <a class="header-anchor" href="#open-the-trace-so-far" aria-label="Permalink to &quot;Open the trace so far&quot;">​</a></h2><p><strong>Open the trace so far</strong> opens Playwright&#39;s trace viewer on the running test&#39;s trace up to now, on the machine the run runs on, with a reporter newer than 0.68.0, while the worker runs a test: beside <strong>Watch</strong> in the VS Code panel (<strong>Piwi: Open the trace so far</strong>), in the JetBrains <strong>Worker</strong> tab, and in a watched page&#39;s head in the Runs window and the tray. The editor service or the desktop app&#39;s server asks the worker where its trace grows, checks that file, and starts the viewer with your project&#39;s own Playwright; the path never leaves it, and each tool hears why when the viewer does not start. Playwright 1.59 to 1.64 shows the trace as it stood when it opened: close it and choose the button again for what came since.</p><p>It shows only where it can open: the machine has a display (on Linux, <code>DISPLAY</code> or <code>WAYLAND_DISPLAY</code> set), the tool knows the run&#39;s folder, and a Runs window reaches the hub without a forwarded port. The attempt must be traced, from its first browser context: <code>trace: &#39;on&#39;</code> or <code>&#39;retain-on-failure&#39;</code> (<code>wrapConfig</code>&#39;s default) traces every attempt, <code>&#39;on-first-retry&#39;</code> and <code>&#39;on-all-retries&#39;</code> a retry alone.</p><h2 id="interact" tabindex="-1">Interact <a class="header-anchor" href="#interact" aria-label="Permalink to &quot;Interact&quot;">​</a></h2><p>At a stop, <strong>Interact</strong>, beside <strong>Watch</strong> once the view is on, sends your clicks, the wheel and your <a href="/reference/keyboard-shortcuts.html#piwi-picker-s-runs-window">keys</a> on the view to the page as a person&#39;s would, the picker and the recorder included. The first takes the stop, so an agent waits until you give it back, and the view names who drives and watches it (<a href="/guide/concepts.html#presence-driving-a-stop">driving a stop</a>). It stays on across the worker&#39;s next stops, where your first input takes the stop again. <strong>Give back</strong>, <code>Esc</code> on the view, watching off or refused, another lane&#39;s stop, a stop that takes no input, the view hidden or closed, or the run&#39;s end turns it off and gives the stop back, once the input sent before has reached the page; what you hold down is let go before the test goes on. While a pick or a check runs on the page, <code>Esc</code> skips the pick or closes the check instead; in a recording it gives the stop back.</p><h2 id="what-is-sent-and-kept" tabindex="-1">What is sent and kept <a class="header-anchor" href="#what-is-sent-and-kept" aria-label="Permalink to &quot;What is sent and kept&quot;">​</a></h2><p>The frames go from the test&#39;s worker only to that worker&#39;s views (an editor&#39;s, the desktop app&#39;s window, Piwi Picker&#39;s Runs window through the extension&#39;s background worker), on your machine or through the port your IDE forwards from a <a href="/guide/remote-development.html">remote window</a>, and to the team instance while the run is <a href="./share-live.html">shared live</a>. The worker takes images only while a view watches it, and paints over password fields and the fields of one-time codes and card numbers first. The editor service or the desktop app&#39;s server passes each on, one view of the page serving every viewer. Nothing stores them.</p><p>The images follow the test&#39;s own screencast: when the test records its own (a video, a trace with screenshots), the view takes its size and quality; when none can start, it is an image of the page twice a second. A frame over 384 KB gives way to a lighter image, twice a second; when even that is too heavy, the view says so.</p><h2 id="limits" tabindex="-1">Limits <a class="header-anchor" href="#limits" aria-label="Permalink to &quot;Limits&quot;">​</a></h2><ul><li><strong>One worker per editor.</strong> The panel or tab watches one worker, a CI run&#39;s lane included: watching another moves it there.</li><li><strong>The test&#39;s <code>page</code>.</strong> A popup or a second page is not shown. A download a click on the view starts and a dialog the page opens go to the test as its own would: Playwright deletes the download with the test&#39;s context, and dismisses the dialog unless the test handles it.</li><li><strong>An older reporter</strong> shows a stopped test alone: the Runs window&#39;s row and the desktop app&#39;s tray hold their <strong>Watch</strong>, saying to update it, and the editors offer no Watch for its workers.</li></ul><h2 id="related" tabindex="-1">Related <a class="header-anchor" href="#related" aria-label="Permalink to &quot;Related&quot;">​</a></h2><ul><li><a href="./editor-run-control.html">Pause and step from the editor</a></li><li><a href="./live-view.html">Live view of a run</a></li><li><a href="./editor-ci-runs.html">CI runs in your editor</a></li></ul>',23))])}const y=s(c,[["render",l]]);export{k as __pageData,y as default};
